1	#include <stdio.h>
2	#include <stdlib.h>
3	#include <string.h>
4	#include "rbtree.h"
5	
6	typedef enum { RED, BLACK } rb_color_t;
7	
8	typedef struct rb_node {
9	    char *key; // Pointer to a copy of string key
10	    void *value; // Pointer storing node's value
11	    rb_color_t color; // Node's color
12	    struct rb_node *parent; // Pointer towards parent node (Above)
13	    struct rb_node *left; // Pointer towards the smaller child node
14	    struct rb_node *right; // Pointer towards the larger child node
15	} rb_node_t;
16	
17	/* The concrete definition of the opaque `rbtree_t` from rbtree.h. Callers only
18	 * ever hold a `struct rbtree *`, so every field here is private and may change
19	 * without touching the graded contract in include/rbtree.h. One of these is
20	 * allocated per tree by rb_create() and released by rb_destroy(). */
21	struct rbtree {
22	    /* Current root of the tree. Points at `nil` (never a raw NULL) when the tree
23	     * is empty, so traversal and fixup code can treat an empty tree and a real
24	     * subtree uniformly. Updated by insert/delete and by the rotation helpers. */
25	    rb_node_t *root;
26	
27	    /* The single shared sentinel standing in for every NULL child and for the
28	     * parent of the root. Allocated once in rb_create(); its `color` is always
29	     * BLACK, and its key/value/child pointers are unused. Using one sentinel
30	     * (rather than NULL) removes the null checks from the red-black fixup and
31	     * lets delete-fixup temporarily write `nil->parent`. Must be freed exactly
32	     * once, by rb_destroy(), after all real nodes are gone. */
33	    rb_node_t *nil;
34	
35	    /* Caller-supplied destructor for owned values, captured from rb_create().
36	     * May be NULL, meaning the tree does not own the values and must not free
37	     * them. When non-NULL it is invoked on the old value when a key is
38	     * overwritten by rb_insert(), on the removed value by rb_delete(), and on
39	     * every remaining value by rb_destroy(). */
40	    rb_value_free_fn value_free;
41	
42	    /* Number of key/value pairs currently stored (excludes the `nil` sentinel).
43	     * Maintained incrementally: +1 on a successful insert of a new key, +0 when
44	     * an insert overwrites an existing key, -1 on a successful delete. Returned
45	     * as-is by rb_size(), which is therefore O(1). */
46	    size_t size;
47	};
48	
49	/* Allocates an empty tree and its `nil` sentinel.
50	 * `value_free` is stored verbatim; NULL means the tree does not own values.
51	 * Returns NULL on allocation failure, having freed any partial allocation. */
52	rbtree_t *rb_create(rb_value_free_fn value_free) {
53	    rbtree_t *t = malloc(sizeof *t);
54	    if (t == NULL) {
55	        return NULL;
56	    }
57	
58	    rb_node_t *nil = malloc(sizeof *nil);
59	    if (nil == NULL) {
60	        goto fail_tree;
61	    }
62	    /* The sentinel is always black; its links point at itself so that a stray
63	     * traversal off a leaf terminates instead of dereferencing NULL. */
64	    nil->key = NULL;
65	    nil->value = NULL;
66	    nil->color = BLACK;
67	    nil->parent = nil;
68	    nil->left = nil;
69	    nil->right = nil;
70	
71	    t->nil = nil;
72	    t->root = nil; /* empty tree: root == nil, never NULL */
73	    t->value_free = value_free;
74	    t->size = 0;
75	    return t;
76	
77	fail_tree:
78	    free(t);
79	    return NULL;
80	}
81	
82	/* Post-order free of one subtree. Depth is O(log n) for a valid RB tree. */
83	static void rb_free_subtree(rbtree_t *t, rb_node_t *n) {
84	    if (n == t->nil) {
85	        return;
86	    }
87	    rb_free_subtree(t, n->left);
88	    rb_free_subtree(t, n->right);
89	    free(n->key);
90	    if (t->value_free != NULL) {
91	        t->value_free(n->value);
92	    }
93	    free(n);
94	}
95	
96	/* Frees every node, key copy, and (if owned) value, then the tree and its
97	 * sentinel. NULL-safe per the contract. */
98	void rb_destroy(rbtree_t *t) {
99	    if (t == NULL) {
100	        return;
101	    }
102	    rb_free_subtree(t, t->root);
103	    free(t->nil);
104	    free(t);
105	}
106	
107	/* Number of key/value pairs stored. NULL-safe, matching rb_destroy's spirit. */
108	size_t rb_size(const rbtree_t *t) {
109	    return (t == NULL) ? 0 : t->size;
110	}
111	
112	/* Recursively checks the subtree rooted at n. Returns that subtree's
113	 * black-height (black nodes on any n-to-nil path, counting the terminal nil),
114	 * or -1 if any red-black or BST invariant is violated within it.
115	 * invariant: on return *prev is the greatest key visited so far by the global
116	 * in-order walk (NULL before the first key), and *count has been incremented
117	 * once per real (non-nil) node visited so far.
118	 * Assumes an acyclic tree; a corrupted cycle would recurse unboundedly (out of
119	 * scope for this milestone). */
120	static int rb_check(const rbtree_t *t, const rb_node_t *n,
121	                    const char **prev, size_t *count) {
122	    if (n == t->nil) {
123	        return 1; /* terminal nil counts as one black node */
124	    }
125	
126	    /* property 2: a red node must not have a red child (nil reads BLACK) */
127	    if (n->color == RED &&
128	        (n->left->color == RED || n->right->color == RED)) {
129	        return -1;
130	    }
131	
132	    int lh = rb_check(t, n->left, prev, count);
133	    if (lh < 0) {
134	        return -1;
135	    }
136	
137	    /* property 4: in-order keys strictly increasing (checked at the in-order
138	     * position, between the left and right recursion) */
139	    if (*prev != NULL && strcmp(*prev, n->key) >= 0) {
140	        return -1;
141	    }
142	    *prev = n->key;
143	    *count += 1; /* property 5: count this real node */
144	
145	    int rh = rb_check(t, n->right, prev, count);
146	    if (rh < 0) {
147	        return -1;
148	    }
149	
150	    /* property 3: both sides have equal black-height */
151	    if (lh != rh) {
152	        return -1;
153	    }
154	
155	    return lh + (n->color == BLACK ? 1 : 0);
156	}
157	
158	/* Returns 0 iff all red-black invariants hold, -1 otherwise. */
159	int rb_validate(const rbtree_t *t) {
160	    if (t == NULL) {
161	        return -1; /* a NULL tree is not a valid RB tree */
162	    }
163	
164	    /* property 1: root is black. Empty tree: root == nil, which is BLACK, so
165	     * the empty tree is accepted here too. */
166	    if (t->root->color != BLACK) {
167	        return -1;
168	    }
169	
170	    const char *prev = NULL; /* greatest key seen by the in-order walk */
171	    size_t count = 0;        /* real nodes seen by the walk */
172	    if (rb_check(t, t->root, &prev, &count) < 0) {
173	        return -1;
174	    }
175	
176	    /* property 5: cached size matches the real node count */
177	    if (count != t->size) {
178	        return -1;
179	    }
180	
181	    return 0;
182	}
183	
184	/* Heap copy of a NUL-terminated key; the tree owns the result. NULL on OOM.
185	 * Not strdup(): under -std=c23 (strict) the glibc headers may not declare it,
186	 * and an implicit declaration would trip -Werror. */
187	static char *dup_key(const char *key) {
188	    size_t n = strlen(key) + 1;
189	    char *copy = malloc(n);
190	    if (copy == NULL) {
191	        return NULL;
192	    }
193	    memcpy(copy, key, n);
194	    return copy;
195	}
196	
197	/* CLRS left rotation, sentinel form. Assumes x->right != t->nil. Retargets
198	 * t->root when x was the root. */
199	static void left_rotate(rbtree_t *t, rb_node_t *x) {
200	    rb_node_t *y = x->right; /* y takes x's slot; x becomes y->left */
201	    x->right = y->left;
202	    if (y->left != t->nil) {
203	        y->left->parent = x;
204	    }
205	    y->parent = x->parent;
206	    if (x->parent == t->nil) {
207	        t->root = y;
208	    } else if (x == x->parent->left) {
209	        x->parent->left = y;
210	    } else {
211	        x->parent->right = y;
212	    }
213	    y->left = x;
214	    x->parent = y;
215	}
216	
217	/* Mirror of left_rotate. Assumes x->left != t->nil. */
218	static void right_rotate(rbtree_t *t, rb_node_t *x) {
219	    rb_node_t *y = x->left; /* y takes x's slot; x becomes y->right */
220	    x->left = y->right;
221	    if (y->right != t->nil) {
222	        y->right->parent = x;
223	    }
224	    y->parent = x->parent;
225	    if (x->parent == t->nil) {
226	        t->root = y;
227	    } else if (x == x->parent->right) {
228	        x->parent->right = y;
229	    } else {
230	        x->parent->left = y;
231	    }
232	    y->right = x;
233	    x->parent = y;
234	}
235	
236	/* CLRS RB-INSERT-FIXUP. z is the freshly linked RED node; restore the red-black
237	 * invariants by recoloring and rotating up the tree. */
238	static void rb_insert_fixup(rbtree_t *t, rb_node_t *z) {
239	    /* invariant: z is RED; the only invariant that can be broken is a red z
240	     * with a red parent. When z is the root, z->parent is t->nil (BLACK) and
241	     * the loop exits immediately. */
242	    while (z->parent->color == RED) {
243	        if (z->parent == z->parent->parent->left) {
244	            rb_node_t *uncle = z->parent->parent->right;
245	            if (uncle->color == RED) {
246	                /* case 1: red uncle -> recolor and move up */
247	                z->parent->color = BLACK;
248	                uncle->color = BLACK;
249	                z->parent->parent->color = RED;
250	                z = z->parent->parent;
251	            } else {
252	                if (z == z->parent->right) {
253	                    /* case 2: triangle -> rotate to a line */
254	                    z = z->parent;
255	                    left_rotate(t, z);
256	                }
257	                /* case 3: line -> recolor and rotate the grandparent */
258	                z->parent->color = BLACK;
259	                z->parent->parent->color = RED;
260	                right_rotate(t, z->parent->parent);
261	            }
262	        } else {
263	            /* mirror image: parent is a right child */
264	            rb_node_t *uncle = z->parent->parent->left;
265	            if (uncle->color == RED) {
266	                z->parent->color = BLACK;
267	                uncle->color = BLACK;
268	                z->parent->parent->color = RED;
269	                z = z->parent->parent;
270	            } else {
271	                if (z == z->parent->left) {
272	                    z = z->parent;
273	                    right_rotate(t, z);
274	                }
275	                z->parent->color = BLACK;
276	                z->parent->parent->color = RED;
277	                left_rotate(t, z->parent->parent);
278	            }
279	        }
280	    }
281	    t->root->color = BLACK;
282	}
283	
284	/* Inserts or overwrites key. On success (return 0) the tree owns value; on any
285	 * failure (return -1) the tree is unchanged and value is NOT consumed. */
286	int rb_insert(rbtree_t *t, const char *key, void *value) {
287	    if (t == NULL || key == NULL) {
288	        return -1; /* invalid args: tree unchanged, value NOT consumed */
289	    }
290	
291	    /* phase 1: read-only BST descent, remembering the parent and last compare.
292	     * invariant: key, if present, is in the subtree rooted at cur; parent is
293	     * cur's parent. */
294	    rb_node_t *parent = t->nil;
295	    rb_node_t *cur = t->root;
296	    int cmp = 0;
297	    while (cur != t->nil) {
298	        cmp = strcmp(key, cur->key);
299	        if (cmp == 0) {
300	            /* overwrite existing key: no structural change, no size change.
301	             * The cur->value != NULL guard avoids handing a NULL to a possibly
302	             * non-NULL-safe value_free. */
303	            if (t->value_free != NULL && cur->value != NULL) {
304	                t->value_free(cur->value);
305	            }
306	            cur->value = value; /* ownership taken on this success path */
307	            return 0;
308	        }
309	        parent = cur;
310	        cur = (cmp < 0) ? cur->left : cur->right;
311	    }
312	
313	    /* phase 2: allocate everything before mutating the tree */
314	    rb_node_t *n = malloc(sizeof *n);
315	    if (n == NULL) {
316	        goto fail;
317	    }
318	    n->key = dup_key(key);
319	    if (n->key == NULL) {
320	        goto fail_node;
321	    }
322	    n->value = value;
323	    n->color = RED;
324	    n->left = t->nil;
325	    n->right = t->nil;
326	    n->parent = parent;
327	
328	    /* phase 3: link the node (no allocation past this point) */
329	    if (parent == t->nil) {
330	        t->root = n; /* first node in the tree */
331	    } else if (cmp < 0) { /* cmp == strcmp(key, parent->key); loop ran >= 1 */
332	        parent->left = n;
333	    } else {
334	        parent->right = n;
335	    }
336	    t->size++;
337	
338	    /* phase 4: restore the red-black invariants */
339	    rb_insert_fixup(t, n);
340	    return 0;
341	
342	fail_node:
343	    free(n);
344	fail:
345	    return -1; /* tree untouched, value not consumed */
346	}
347	
348	/* Returns the value stored under key, or NULL if absent. Tree retains ownership. */
349	void *rb_find(const rbtree_t *t, const char *key) {
350	    if (t == NULL || key == NULL) {
351	        return NULL;
352	    }
353	    const rb_node_t *x = t->root;
354	    /* invariant: key, if present, lies in the subtree rooted at x */
355	    while (x != t->nil) {
356	        int c = strcmp(key, x->key);
357	        if (c == 0) {
358	            return x->value;
359	        }
360	        x = (c < 0) ? x->left : x->right;
361	    }
362	    return NULL;
363	}
364	
365	/* In-order visit of the subtree rooted at n: left, then n itself, then right.
366	 * invariant: every real node in the subtree is visited exactly once, in
367	 * strictly increasing key order. */
368	static void rb_foreach_subtree(const rbtree_t *t, const rb_node_t *n,
369	                                void (*fn)(const char *key, void *value, void *ctx),
370	                                void *ctx) {
371	    if (n == t->nil) {
372	        return;
373	    }
374	    rb_foreach_subtree(t, n->left, fn, ctx);
375	    fn(n->key, n->value, ctx);
376	    rb_foreach_subtree(t, n->right, fn, ctx);
377	}
378	
379	/* In-order traversal; visits nothing on a NULL tree or NULL callback. */
380	void rb_foreach(const rbtree_t *t,
381	                void (*fn)(const char *key, void *value, void *ctx),
382	                void *ctx) {
383	    if (t == NULL || fn == NULL) {
384	        return;
385	    }
386	    rb_foreach_subtree(t, t->root, fn, ctx);
387	}
388	
389	/* CLRS RB-TRANSPLANT. Replaces the subtree rooted at u with the subtree
390	 * rooted at v, from u->parent's perspective; does not touch u's or v's own
391	 * children/color. The final assignment runs even when v == t->nil, which is
392	 * exactly the "delete-fixup temporarily writes nil->parent" mechanism the
393	 * struct comment on `nil` anticipates: it gives x (in rb_delete_fixup) a
394	 * well-defined parent even when x is the sentinel. */
395	static void rb_transplant(rbtree_t *t, rb_node_t *u, rb_node_t *v) {
396	    if (u->parent == t->nil) {
397	        t->root = v;
398	    } else if (u == u->parent->left) {
399	        u->parent->left = v;
400	    } else {
401	        u->parent->right = v;
402	    }
403	    v->parent = u->parent;
404	}
405	
406	/* CLRS TREE-MINIMUM. Assumes n != t->nil. Returns the leftmost (smallest-key)
407	 * node in the subtree rooted at n. */
408	static rb_node_t *rb_minimum(rbtree_t *t, rb_node_t *n) {
409	    /* invariant: n is never nil; each step strictly descends left */
410	    while (n->left != t->nil) {
411	        n = n->left;
412	    }
413	    return n;
414	}
415	
416	/* CLRS RB-DELETE-FIXUP. x is the node that moved into a spliced-out node's
417	 * position (possibly t->nil) and carries one extra unit of black-ness;
418	 * restore the red-black invariants by recoloring and rotating up the tree.
419	 * Precondition: x->parent is already correct, even when x == t->nil (see
420	 * rb_transplant and the y->parent == z case in rb_delete). */
421	static void rb_delete_fixup(rbtree_t *t, rb_node_t *x) {
422	    /* invariant: x is doubly-black (or red-and-black); the loop climbs until
423	     * x reaches the root or picks up enough redness to absorb locally. */
424	    while (x != t->root && x->color == BLACK) {
425	        if (x == x->parent->left) {
426	            rb_node_t *sibling = x->parent->right;
427	            if (sibling->color == RED) {
428	                /* case 1: red sibling -> rotate to get a black sibling */
429	                sibling->color = BLACK;
430	                x->parent->color = RED;
431	                left_rotate(t, x->parent);
432	                sibling = x->parent->right;
433	            }
434	            if (sibling->left->color == BLACK && sibling->right->color == BLACK) {
435	                /* case 2: both nephews black -> recolor and move up */
436	                sibling->color = RED;
437	                x = x->parent;
438	            } else {
439	                if (sibling->right->color == BLACK) {
440	                    /* case 3: near nephew red -> rotate to a case-4 shape */
441	                    sibling->left->color = BLACK;
442	                    sibling->color = RED;
443	                    right_rotate(t, sibling);
444	                    sibling = x->parent->right;
445	                }
446	                /* case 4: far nephew red -> recolor and rotate, done */
447	                sibling->color = x->parent->color;
448	                x->parent->color = BLACK;
449	                sibling->right->color = BLACK;
450	                left_rotate(t, x->parent);
451	                x = t->root;
452	            }
453	        } else {
454	            /* mirror image: x is a right child */
455	            rb_node_t *sibling = x->parent->left;
456	            if (sibling->color == RED) {
457	                sibling->color = BLACK;
458	                x->parent->color = RED;
459	                right_rotate(t, x->parent);
460	                sibling = x->parent->left;
461	            }
462	            if (sibling->right->color == BLACK && sibling->left->color == BLACK) {
463	                sibling->color = RED;
464	                x = x->parent;
465	            } else {
466	                if (sibling->left->color == BLACK) {
467	                    sibling->right->color = BLACK;
468	                    sibling->color = RED;
469	                    left_rotate(t, sibling);
470	                    sibling = x->parent->left;
471	                }
472	                sibling->color = x->parent->color;
473	                x->parent->color = BLACK;
474	                sibling->left->color = BLACK;
475	                right_rotate(t, x->parent);
476	                x = t->root;
477	            }
478	        }
479	    }
480	    x->color = BLACK; /* safe no-op when x == t->nil: nil->color is always BLACK */
481	}
482	
483	/* Removes key; frees the key copy and (if owned) the value. Returns 0, or -1
484	 * if key is absent (tree unchanged). */
485	int rb_delete(rbtree_t *t, const char *key) {
486	    if (t == NULL || key == NULL) {
487	        return -1;
488	    }
489	
490	    /* phase 1: BST search for z, mirroring rb_find's descent.
491	     * invariant: key, if present, lies in the subtree rooted at z */
492	    rb_node_t *z = t->root;
493	    while (z != t->nil) {
494	        int c = strcmp(key, z->key);
495	        if (c == 0) {
496	            break;
497	        }
498	        z = (c < 0) ? z->left : z->right;
499	    }
500	    if (z == t->nil) {
501	        return -1; /* absent: tree, size, and validity all unchanged */
502	    }
503	
504	    /* phase 2: CLRS splice. y is the node actually removed from its spot
505	     * (equal to z unless z has two children); x is the node that lands in
506	     * y's old position, possibly t->nil. */
507	    rb_node_t *y = z;
508	    rb_color_t y_original_color = y->color;
509	    rb_node_t *x;
510	
511	    if (z->left == t->nil) {
512	        x = z->right;
513	        rb_transplant(t, z, z->right);
